     1|/**
     2| * IVX IA Conversation Brain — general-purpose, owner-token-gated direct answers.
     3| *
     4| * Owner spec:
     5| *   - The brain can have regular conversation and answer ANY type of question.
     6| *   - If it can be answered deterministically (math, general knowledge, greeting,
     7| *     help, capabilities), answer directly — never route to the bearer-guarded
     8| *     pipeline that returns 401 for owner-token-only requests.
     9| *
    10| * This is a fast, deterministic path that runs AFTER the identity/senior-dev
    11| * brains but BEFORE the Supabase-bearer-guarded main pipeline. It never blocks
    12| * and never asks for proof — it is the IVX IA conversational persona.
    13| */
    14|
    15|export const IVX_IA_CONVERSATION_MARKER = 'ivx-ia-conversation-brain-2026-07-06';
    16|
    17|/**
    18| * Detect a general conversation question that can be answered deterministically.
    19| * Returns the question type or 'none'.
    20| */
    21|export type IVXConversationType =
    22|  | 'math'
    23|  | 'percentage'
    24|  | 'greeting'
    25|  | 'thanks'
    26|  | 'capabilities'
    27|  | 'help'
    28|  | 'yes_no'
    29|  | 'definition'
    30|  | 'none';
    31|
    32|export function detectIVXConversationQuestion(message: string): IVXConversationType {
    33|  const text = (message ?? '').toLowerCase().replace(/[^a-z0-9\s+\-*/=.%]/g, ' ');
    34|  const compact = text.replace(/\s+/g, ' ').trim();
    35|  if (!compact) return 'none';
    36|
    37|  // Math: "15 multiplied by 3", "15 * 3", "what is 15 x 3", "10 plus 5",
    38|  // "100 minus 20", "50 divided by 2", "square root of 144"
    39|  if (detectMathQuestion(compact)) return 'math';
    40|
    41|  // Percentage: "what is 15% of 50000", "15 percent of 80000"
    42|  // Check BEFORE definition — "what is 15% of 50000" starts with "what is"
    43|  if (detectPercentageQuestion(compact)) return 'percentage';
    44|
    45|  // Yes/No: simple questions that can be answered yes or no
    46|  if (detectYesNoQuestion(compact)) return 'yes_no';
    47|
    48|  // Definition: "what is a REIT", "define DST", "what does JV mean"
    49|  if (detectDefinitionQuestion(compact)) return 'definition';
    50|
    51|  // Greetings
    52|  const greetings = ['hello', 'hi ', 'hey', 'hola', 'good morning', 'good afternoon', 'good evening', 'buenos dias', 'buenas tardes'];
    53|  if (greetings.some((g) => compact === g.trim() || compact.startsWith(g) || compact === g.trim())) return 'greeting';
    54|
    55|  // Thanks
    56|  const thanks = ['thank you', 'thanks', 'gracias', 'much appreciated', 'ty '];
    57|  if (thanks.some((t) => compact === t.trim() || compact.startsWith(t))) return 'thanks';
    58|
    59|  // Capabilities / "what can you do"
    60|  const capPhrases = ['what can you do', 'what do you do', 'help me with', 'your capabilities', 'what are your features', 'what are you able to do', 'que puedes hacer'];
    61|  if (capPhrases.some((p) => compact.includes(p))) return 'capabilities';
    62|
    63|  // Help
    64|  if (compact === 'help' || compact.startsWith('help ') || compact.includes('can you help')) return 'help';
    65|
    66|  return 'none';
    67|}
    68|
    69|/**
    70| * Detect and evaluate a math question.
    71| * Handles: plus, minus, multiplied by, times, divided by, x, *, /, +, -, sqrt.
    72| */
    73|function detectMathQuestion(compact: string): boolean {
    74|  // Word-form arithmetic
    75|  const wordMath = /\b(\d+(?:\.\d+)?)\s+(plus|minus|multiplied by|times|divided by|added to|subtracted from)\s+(\d+(?:\.\d+)?)/;
    76|  if (wordMath.test(compact)) return true;
    77|  // Symbol-form arithmetic (single regex test — removed redundant double check)
    78|  const symMath = /\b(\d+(?:\.\d+)?)\s*[+\-*/x]\s*(\d+(?:\.\d+)?)/;
    79|  if (symMath.test(compact)) return true;
    80|  // "what is N op N"
    81|  if (/\bwhat is\s+/.test(compact) && wordMath.test(compact)) return true;
    82|  // square root
    83|  if (/\b(square root|sqrt)\s+of\s+\d+/.test(compact)) return true;
    84|  return false;
    85|}
    86|
    87|/**
    88| * Detect a percentage question: "what is 15% of 50000", "15 percent of 80000".
    89| */
    90|function detectPercentageQuestion(compact: string): boolean {
    91|  return /\b\d+(?:\.\d+)?\s*(%|percent)\s+of\s+\d+/i.test(compact);
    92|}
    93|
    94|/**
    95| * Evaluate a percentage expression from natural language.
    96| */
    97|function evaluatePercentageQuestion(message: string): number | null {
    98|  const text = (message ?? '').toLowerCase().replace(/[^a-z0-9\s%.]/g, ' ').replace(/\s+/g, ' ').trim();
    99|  const match = text.match(/(\d+(?:\.\d+)?)\s*(?:%|percent)\s+of\s+(\d+(?:\.\d+)?)/);
   100|  if (!match) return null;
   101|  const pct = parseFloat(match[1]);
   102|  const base = parseFloat(match[2]);
   103|  if (!isFinite(pct) || !isFinite(base)) return null;
   104|  return (pct / 100) * base;
   105|}
   106|
   107|/**
   108| * Detect a yes/no question that can be answered deterministically.
   109| */
   110|function detectYesNoQuestion(compact: string): boolean {
   111|  // "is ivx a reit", "can i invest", "does ivx offer tokenization"
   112|  if (/^(is|are|can|do|does|will|should|has|have)\b/.test(compact) && compact.length < 120) return true;
   113|  return false;
   114|}
   115|
   116|/**
   117| * Answer a yes/no question about IVX.
   118| */
   119|function answerYesNoQuestion(message: string): string | null {
   120|  const text = (message ?? '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
   121|  // IVX-specific yes/no answers
   122|  if (/\b(is|are)\b.*\b(reit|dst|1031)\b/.test(text)) {
   123|    return 'No, IVX Holdings is not a REIT or DST. IVX is a real-estate joint-venture platform that offers fractional ownership in specific projects, not a traded trust entity.';
   124|  }
   125|  if (/\bcan\b.*\b(invest|buy|participate)\b/.test(text)) {
   126|    return 'Yes, you can invest through IVX Holdings by reviewing available projects and participating with fractional ownership. Visit ivxholding.com to see current offerings.';
   127|  }
   128|  if (/\b(does|do)\b.*\b(tokeniz|wallet|withdraw|wire)/.test(text)) {
   129|    return 'Yes, IVX Holdings supports tokenization, wallet management, withdrawals, and wire transfers for qualified investors.';
   130|  }
   131|  if (/\b(is|are)\b.*\b(legit|safe|secure|regulated)\b/.test(text)) {
   132|    return 'Yes, IVX Holdings operates with proper corporate structure and compliance. All investments are documented through formal JV agreements.';
   133|  }
   134|  // Generic fallback — don't guess, route to AI
   135|  return null;
   136|}
   137|
   138|/**
   139| * Detect a definition question: "what is a REIT", "define DST", "what does JV mean".
   140| */
   141|function detectDefinitionQuestion(compact: string): boolean {
   142|  if (/^(what is|what are|what does|define|explain)\b/.test(compact) && compact.length < 150) return true;
   143|  return false;
   144|}
   145|
   146|/**
   147| * Answer a definition question about real estate / IVX terms.
   148| */
   149|function answerDefinitionQuestion(message: string): string | null {
   150|  const text = (message ?? '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
   151|  const definitions: Array<{ terms: string[]; answer: string }> = [
   152|    { terms: ['reit'], answer: 'A REIT (Real Estate Investment Trust) is a company that owns, operates, or finances income-generating real estate. Investors buy shares and receive dividends, but do not directly own the properties.' },
   153|    { terms: ['dst'], answer: 'A DST (Delaware Statutory Trust) is a legal entity used for 1031 exchanges, allowing investors to exchange one property for fractional interests in multiple properties without immediate capital gains tax.' },
   154|    { terms: ['jv', 'joint venture'], answer: 'A JV (Joint Venture) is a business arrangement where two or more parties pool resources for a specific project. In real estate, JVs combine capital, expertise, and property ownership.' },
   155|    { terms: ['1031'], answer: 'A 1031 exchange is a tax-deferred swap of investment properties under IRC Section 1031, allowing investors to defer capital gains taxes when reinvesting proceeds into a like-kind property.' },
   156|    { terms: ['fractional', 'fractional ownership'], answer: 'Fractional ownership allows multiple investors to share ownership of a single asset, each holding a percentage. It reduces the minimum investment and diversifies risk.' },
   157|    { terms: ['tokeniz', 'tokenization'], answer: 'Tokenization is the process of representing ownership rights as digital tokens on a blockchain, enabling fractional ownership and easier transfer of real estate interests.' },
   158|    { terms: ['cap rate', 'capitalization rate'], answer: 'Cap rate (capitalization rate) is the ratio of net operating income to property value, expressed as a percentage. It measures the potential return on a real estate investment.' },
   159|    { terms: ['roi', 'return on investment'], answer: 'ROI (Return on Investment) measures the profitability of an investment relative to its cost, expressed as a percentage. In real estate, it includes rental income plus appreciation.' },
   160|    { terms: ['irr', 'internal rate of return'], answer: 'IRR (Internal Rate of Return) is the annualized rate of return that makes the net present value of all cash flows equal zero. It accounts for the time value of money in real estate projections.' },
   161|    { terms: ['waterfall', 'waterfall distribution'], answer: 'A waterfall distribution is a tiered allocation of profits in a real estate JV. Returns are distributed in priority order: capital returned first, then preferred return, then sponsor promote, then remaining split.' },
   162|    { terms: ['preferred return', 'pref'], answer: 'A preferred return (pref) is a minimum return percentage promised to investors before the sponsor receives their promote. Common in real estate JVs, typically 6-10% annually.' },
   163|    { terms: ['promote', 'sponsor promote'], answer: 'Sponsor promote is the performance fee earned by the JV sponsor for exceeding the preferred return. It aligns sponsor and investor incentives — the sponsor earns more when returns are higher.' },
   164|    { terms: ['k1', 'schedule k-1'], answer: 'A Schedule K-1 is a tax form reporting each partner\'s share of income, losses, deductions, and credits from a partnership. Real estate JV investors receive K-1s annually for tax filing.' },
   165|    { terms: ['accredited investor'], answer: 'An accredited investor is an individual with net worth over $1M (excluding primary residence) or annual income over $200K ($300K joint). Many private real estate offerings require accredited investor status.' },
   166|  ];
   167|  for (const def of definitions) {
