   169|  }
   170|  return null;
   171|}
   172|
   173|/**
   174| * Evaluate a math expression from natural language.
   175| */
   176|function evaluateMathQuestion(message: string): number | null {
   177|  const text = (message ?? '').toLowerCase().replace(/[^a-z0-9\s+\-*/=.]/g, ' ').replace(/\s+/g, ' ').trim();
   178|  // square root
   179|  const sqrtMatch = text.match(/(?:square root|sqrt)\s+of\s+(\d+(?:\.\d+)?)/);
   180|  if (sqrtMatch) {
   181|    const n = parseFloat(sqrtMatch[1]);
   182|    return Math.sqrt(n);
   183|  }
   184|  // word-form
   185|  const wordMatch = text.match(/(\d+(?:\.\d+)?)\s+(plus|minus|multiplied by|times|divided by|added to|subtracted from)\s+(\d+(?:\.\d+)?)/);
   186|  if (wordMatch) {
   187|    const a = parseFloat(wordMatch[1]);
   188|    const op = wordMatch[2];
   189|    const b = parseFloat(wordMatch[3]);
   190|    switch (op) {
   191|      case 'plus': case 'added to': return a + b;
   192|      case 'minus': case 'subtracted from': return op === 'subtracted from' ? b - a : a - b;
   193|      case 'multiplied by': case 'times': return a * b;
   194|      case 'divided by': return b === 0 ? null : a / b;
   195|    }
   196|  }
   197|  // symbol-form: "what is 15 x 3" / "15 * 3" / "10 + 5"
   198|  const symMatch = text.match(/(\d+(?:\.\d+)?)\s*([+\-*/x])\s*(\d+(?:\.\d+)?)/);
   199|  if (symMatch) {
   200|    const a = parseFloat(symMatch[1]);
   201|    const op = symMatch[2];
   202|    const b = parseFloat(symMatch[3]);
   203|    switch (op) {
   204|      case '+': return a + b;
   205|      case '-': return a - b;
   206|      case '*': case 'x': return a * b;
   207|      case '/': return b === 0 ? null : a / b;
   208|    }
   209|  }
